<script setup>
import { onMounted, proxyRefs } from 'vue';import { useStockChecklist } from '../../../composables/useStockChecklist';const stock=proxyRefs(useStockChecklist());onMounted(()=>stock.load());
</script>
<template><section class="stock-panel"><div class="stock-panel-head"><div><h2>Physical Stock Check List</h2><p>Stock reconciliation records and approval status.</p></div><button :disabled="stock.loading" @click="stock.load({force:true})">{{stock.loading?'Loading…':'↻ Refresh'}}</button></div><div class="stock-report-controls"><label>Search<input v-model="stock.query" type="search" placeholder="Name, warehouse, owner"></label><label>Status<select v-model="stock.status"><option value="all">All statuses</option><option>Pending Stock Manager Approval</option><option>Approved</option><option>Rejected</option><option>Submitted</option></select></label></div><p v-if="stock.error" class="stock-error">{{stock.error}}</p><p v-if="stock.loading" class="stock-loading">Loading verification records…</p><div class="stock-table-wrap"><table><thead><tr><th>Reconciliation</th><th>Date</th><th>Warehouse</th><th>Workflow status</th><th>Difference amount</th><th>Created by</th><th>ERP</th></tr></thead><tbody><tr v-for="row in stock.rows" :key="row.name"><td>{{row.name}}</td><td>{{String(row.posting_date||'').slice(0,10)||'—'}}</td><td>{{row.set_warehouse||'—'}}</td><td><span class="stock-status">{{row.workflow_state||'—'}}</span></td><td>{{row.difference_amount??'—'}}</td><td>{{row.owner||'—'}}</td><td><a class="stock-document-link" :href="`/app/stock-reconciliation/${encodeURIComponent(row.name)}`" target="_blank" rel="noopener">Open</a></td></tr><tr v-if="!stock.loading&&!stock.rows.length"><td colspan="7" class="stock-empty">No verification records match the filters.</td></tr></tbody></table></div></section></template>
